// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/healthz", wrapper.Health)
	m.HandleFunc("GET "+options.BaseURL+"/readyz", wrapper.Ready)
	m.HandleFunc("POST "+options.BaseURL+"/v1/admissions", wrapper.CreateAdmission)
	m.HandleFunc("POST "+options.BaseURL+"/v1/admissions/{admissionId}:consume", wrapper.ConsumeAdmission)
	m.HandleFunc("POST "+options.BaseURL+"/v1/admissions/{admissionId}:release", wrapper.ReleaseAdmission)
	m.HandleFunc("POST "+options.BaseURL+"/v1/admissions/{admissionId}:renew", wrapper.RenewAdmission)
	m.HandleFunc("POST "+options.BaseURL+"/v1/admissions/{admissionId}:verify", wrapper.VerifyAdmission)
	m.HandleFunc("GET "+options.BaseURL+"/v1/bans", wrapper.ListBans)
	m.HandleFunc("POST "+options.BaseURL+"/v1/bans", wrapper.CreateBan)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/bans/{banId}", wrapper.RevokeBan)
	m.HandleFunc("POST "+options.BaseURL+"/v1/challenges", wrapper.IssueChallenge)
	m.HandleFunc("POST "+options.BaseURL+"/v1/challenges/{challengeId}:verify", wrapper.VerifyChallenge)
	m.HandleFunc("POST "+options.BaseURL+"/v1/login-attempts", wrapper.BeginLoginAttempt)
	m.HandleFunc("POST "+options.BaseURL+"/v1/login-attempts/{attemptId}:finish", wrapper.FinishLoginAttempt)
	m.HandleFunc("GET "+options.BaseURL+"/v1/policies", wrapper.GetPolicy)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/policies", wrapper.UpdatePolicy)
	m.HandleFunc("POST "+options.BaseURL+"/v1/question-risk", wrapper.ReportModelRisk)
	m.HandleFunc("GET "+options.BaseURL+"/v1/risk-events", wrapper.ListRiskEvents)
	m.HandleFunc("POST "+options.BaseURL+"/v1/session-queue", wrapper.QueueSessionAdmission)

	return m
}

